-- Paste ALL of this into Supabase -> SQL Editor -> New query -> Run, once. It is one transaction: if anything
-- fails, nothing is changed. Confirm the 'destructive operation' warning (it comes from 'create or replace' and
-- 'drop ... if exists' lines; no data is deleted). The checks at the end fail the whole paste if a piece is missing.
-- Generated by scripts/build-production-sql.mjs from supabase/migrations/20261012000040_estate_agents.sql .. 20261012000040_estate_agents.sql;
-- do not edit by hand.
begin;

-- Run the new categories script (docs/launch/new-categories-production.sql) first: this stops (changing nothing) if it hasn't been.
do $requires$
begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012000039') then
    raise exception 'Run the new categories script (docs/launch/new-categories-production.sql) first: migration 20261012000039 is not recorded';
  end if;
end
$requires$;

-- ==== 20261012000040_estate_agents.sql
-- Estate agents, requested by the owner. In Moving & waste, where people moving house look. Every UK estate agent must
-- belong to a government-approved redress scheme (Consumers, Estate Agents and Redress Act 2007), so the guidance says
-- to ask which. Idempotent: safe to run again.
insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, 'estate-agents', 'Estate agents', 'none'::public.category_requirement,
  'Estate agents must belong to a government-approved redress scheme (The Property Ombudsman or the Property Redress Scheme). Ask which one before you sign.'
from public.category_groups g where g.slug = 'moving-waste'
on conflict (slug) do nothing;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000040', 'estate_agents') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
begin
  if not exists (select 1 from public.categories c join public.category_groups g on g.id = c.group_id
                 where c.slug = 'estate-agents' and c.active and g.slug = 'moving-waste' and c.guidance_note like '%redress scheme%') then
    raise exception 'Estate agents check failed: the category is missing';
  end if;
end
$verify$;

commit;

select 'Estate agents applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000040')) as migrations_recorded;
